 * Returns the first $k characters of the given string.
 *
 * @param string $s  Input string
 * @param int    $k  Number of characters to return
 * @return string    First $k characters, or the whole string if $k >= length
 */
function getFirstKChars(string $s, int $k): string
{
    $len = strlen($s);

    if ($k <= 0) {
        return '';
    }

    if ($k >= $len) {
        return $s;
    }

    return substr($s, 0, $k);
